package domain

import (
	"context"
	"time"

	"github.com/google/uuid"

	pd "github.com/aliyyulmanbinus/adicara-platform/backend/internal/modules/planner/domain"
)

// SessionRef is the part of a session (menu 01) the module reads: the scope check, the summaries and the WhatsApp text.
type SessionRef struct {
	ID        uuid.UUID
	ScopeKey  string
	Name      string
	Icon      string
	IsSystem  bool
	SortOrder int
	Date      *time.Time // session_date, 00:00 UTC
	Location  *string    // location_name
}

// AgendaWrite is the writable part of a planner_rundowns row. The duration is generated by the database and the status
// only moves through SetAgendaStatus. SortOrder is used by the template reset only; an insert takes max + 1 of its
// session.
type AgendaWrite struct {
	ID           uuid.UUID
	SessionID    uuid.UUID
	Times        Times
	ActivityName string
	PICName      string
	VendorID     *uuid.UUID
	Description  string
	Highlights   string
	TemplateKey  *string
	SortOrder    int
}

// SongWrite is the writable part of a planner_playlists row.
type SongWrite struct {
	ID          uuid.UUID
	RundownID   *uuid.UUID
	SongTitle   string
	Artist      string
	MomentTag   string
	AudioFormat AudioFormat
	SpotifyURL  *string
	YouTubeURL  *string
	CueNotes    *string
	Status      AudioStatus
	TemplateKey *string
}

// TemplateAgendaState is an agenda of the project that came from the template, as replace_template has to treat it.
type TemplateAgendaState struct {
	ID        uuid.UUID
	SessionID uuid.UUID
	Status    RundownStatus
}

// Repository is the PostgreSQL side of the module. Every method that takes a projectID filters by it; ids that come
// from a URL are always looked up with both (WHERE id = $x AND project_id = $y).
type Repository interface {
	// LockProject takes SELECT … FOR UPDATE on the project row. Needs a transaction.
	LockProject(ctx context.Context, projectID uuid.UUID) error
	// Sessions are the sessions of the project in display order, the system session included.
	Sessions(ctx context.Context, projectID uuid.UUID) ([]SessionRef, error)

	// ---------- agendas ----------
	// ListAgendas returns the agendas in display order (session, sort_order, start); sessionID narrows to one session.
	ListAgendas(ctx context.Context, projectID uuid.UUID, sessionID *uuid.UUID) ([]Rundown, error)
	AgendaByID(ctx context.Context, projectID, id uuid.UUID) (Rundown, error)
	// SessionSummaries: one row per non-system session, with zeroes for a session without agendas (06 BE 2.8).
	SessionSummaries(ctx context.Context, projectID uuid.UUID) ([]RundownSessionSummary, error)
	// DistinctPICs counts the people in charge: a linked vendor once, otherwise the pic_name as typed (06 BE 2.1).
	DistinctPICs(ctx context.Context, projectID uuid.UUID) (int, error)
	LiveItems(ctx context.Context, projectID uuid.UUID) ([]RundownLiveItem, error)
	CountAgendas(ctx context.Context, projectID uuid.UUID) (int, error)
	// InsertAgenda appends the agenda (sort_order = max + 1 of its session). ErrInvalidVendor for a vendor of another project.
	InsertAgenda(ctx context.Context, projectID uuid.UUID, a *AgendaWrite) error
	// UpdateAgenda writes everything but the status and the template key; moving to another session puts the agenda last there.
	UpdateAgenda(ctx context.Context, projectID uuid.UUID, a *AgendaWrite) error
	// SetAgendaStatus is the one statement that writes the status and its two time stamps (06 BE 2.3).
	SetAgendaStatus(ctx context.Context, projectID, id uuid.UUID, status RundownStatus) error
	DeleteAgenda(ctx context.Context, projectID, id uuid.UUID) error
	// AgendaIDs are the ids of the agendas of one session.
	AgendaIDs(ctx context.Context, projectID, sessionID uuid.UUID) ([]uuid.UUID, error)
	// ReorderAgendas gives the agendas of the session sort_order 1..n in the order of ids (06 BE 2.5).
	ReorderAgendas(ctx context.Context, projectID, sessionID uuid.UUID, ids []uuid.UUID) error

	// ---------- agenda template ----------
	// TemplateAgendaStates reads the agendas of the project that carry one of the template keys, by key.
	TemplateAgendaStates(ctx context.Context, projectID uuid.UUID, keys []string) (map[string]TemplateAgendaState, error)
	// InsertTemplateAgenda inserts unless the template_key exists in the project; the agenda goes last in its session.
	InsertTemplateAgenda(ctx context.Context, projectID uuid.UUID, a *AgendaWrite) (inserted bool, err error)
	// ResetTemplateAgenda puts the template content of an agenda back: times, name, PIC, description, highlights and
	// sort_order. The id, the vendor, the session, the status and the songs that point at it stay.
	ResetTemplateAgenda(ctx context.Context, projectID, id uuid.UUID, a *AgendaWrite) error

	// ---------- playlist ----------
	ListPlaylists(ctx context.Context, projectID uuid.UUID) ([]Playlist, error)
	PlaylistByID(ctx context.Context, projectID, id uuid.UUID) (Playlist, error)
	CountPlaylists(ctx context.Context, projectID uuid.UUID) (int, error)
	// InsertPlaylist appends the song (sort_order = max + 1). ErrInvalidAgenda for an agenda of another project.
	InsertPlaylist(ctx context.Context, projectID uuid.UUID, s *SongWrite) error
	UpdatePlaylist(ctx context.Context, projectID uuid.UUID, s *SongWrite) error
	DeletePlaylist(ctx context.Context, projectID, id uuid.UUID) error
	PlaylistIDs(ctx context.Context, projectID uuid.UUID) ([]uuid.UUID, error)
	ReorderPlaylists(ctx context.Context, projectID uuid.UUID, ids []uuid.UUID) error
	InsertTemplateSong(ctx context.Context, projectID uuid.UUID, s *SongWrite) (inserted bool, err error)

	// ---------- dashboard widget ----------
	// Dashboard is the rundown widget of menu 01 (01 BE 5.2). today is the calendar day in the project's zone (the
	// usecase's clock, so a test can fix it) and decides which session is the next one.
	Dashboard(ctx context.Context, projectID uuid.UUID, today time.Time) (pd.RundownSummary, error)
}
